const res = $input.first().json;

if (res.statusCode !== 200) {
  throw new Error(`Summary fetch failed: ${res.statusCode} ${JSON.stringify(res.body)}`);
}

const s = res.body;
const rs = (paise) => '₹' + ((paise ?? 0) / 100).toLocaleString('en-IN');

// Chapter 9 ka insight: jo system dikhta nahi, uske paise dene ka mann nahi
// karta. Isliye ye message chhota aur roz aana chahiye.
const lines = [
  `Aaj ka hisaab (${s.date ?? new Date().toISOString().slice(0, 10)}):`,
  ``,
  `Sales: ${rs(s.sales)}  ·  ${s.bills ?? 0} bill`,
  `Cash: ${rs(s.received_by_mode?.cash)}   UPI: ${rs(s.received_by_mode?.upi)}`,
  `Udhaar diya: ${rs(s.credit_given)}`,
  `Kharcha: ${rs(s.expenses)}`,
];

return [{ json: { text: lines.join('\n') } }];
